-- ============================================================================
-- 页面装修类型升级
-- Source: db/boot/10page_design_alter.sql
-- ============================================================================
USE aryn_boot;

ALTER TABLE page_design ADD COLUMN page_type char(2) NOT NULL DEFAULT '0' COMMENT '页面类型：0.微页面；1.首页；' AFTER page_content;

UPDATE page_design SET page_type = '1' WHERE home_status = '1';

-- ============================================================================
-- 页面装修发布与模板
-- Source: db/boot/11page_design_publish.sql
-- ============================================================================
USE aryn_boot;

ALTER TABLE page_design
    ADD COLUMN draft_revision bigint NOT NULL DEFAULT 0 COMMENT '草稿修订号' AFTER page_content,
    ADD COLUMN schema_version int NOT NULL DEFAULT 1 COMMENT '装修协议版本' AFTER draft_revision,
    ADD COLUMN published_version_id varchar(32) NULL COMMENT '当前发布版本ID' AFTER schema_version,
    ADD COLUMN published_status char(2) NOT NULL DEFAULT '0' COMMENT '发布状态：0.未发布；1.已发布；' AFTER published_version_id,
    ADD COLUMN published_at datetime NULL COMMENT '发布时间' AFTER published_status,
    ADD COLUMN legacy_content_backup longtext NULL COMMENT '旧版装修内容备份' AFTER published_at;

CREATE TABLE page_design_version (
    id varchar(32) NOT NULL COMMENT '主键',
    page_design_id varchar(32) NOT NULL COMMENT '页面ID',
    version_no int NOT NULL COMMENT '版本号',
    schema_version int NOT NULL DEFAULT 1 COMMENT '装修协议版本',
    page_name varchar(50) NOT NULL COMMENT '发布时页面名称',
    page_type char(2) NOT NULL COMMENT '页面类型：0.微页面；1.首页；',
    page_content longtext NOT NULL COMMENT '发布页面内容',
    publish_remark varchar(255) NULL COMMENT '发布备注',
    publish_by varchar(60) NULL COMMENT '发布人',
    published_at datetime NOT NULL COMMENT '发布时间',
    create_by varchar(60) NULL COMMENT '创建人',
    create_time datetime NULL COMMENT '创建时间',
    del_flag char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
    tenant_id varchar(32) NOT NULL COMMENT '租户ID',
    PRIMARY KEY (id),
    UNIQUE KEY uk_page_design_tenant_version (tenant_id, page_design_id, version_no),
    KEY idx_page_design_published_at (page_design_id, published_at)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '页面装修发布版本表';

CREATE TABLE page_design_template (
    id varchar(32) NOT NULL COMMENT '主键',
    template_name varchar(100) NOT NULL COMMENT '模板名称',
    template_type char(2) NOT NULL DEFAULT '0' COMMENT '模板类型：0.页面；1.组件组合；',
    page_type char(2) NOT NULL DEFAULT '2' COMMENT '页面类型：0.微页面；1.首页；2.通用；',
    template_content longtext NOT NULL COMMENT '模板内容',
    schema_version int NOT NULL DEFAULT 2 COMMENT '装修协议版本',
    system_flag char(2) NOT NULL DEFAULT '0' COMMENT '系统模板：0.否；1.是；',
    status char(2) NOT NULL DEFAULT '0' COMMENT '状态：0.正常；1.停用；',
    sort int NOT NULL DEFAULT 0 COMMENT '排序',
    create_by varchar(60) NULL COMMENT '创建人',
    update_by varchar(60) NULL COMMENT '修改人',
    create_time datetime NULL COMMENT '创建时间',
    update_time datetime NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    del_flag char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
    tenant_id varchar(32) NOT NULL COMMENT '租户ID',
    PRIMARY KEY (id),
    KEY idx_page_design_template_tenant (tenant_id, template_type, status)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '页面装修模板表';

UPDATE page_design
SET legacy_content_backup = page_content,
    published_status = CASE WHEN status = '0' THEN '1' ELSE '0' END,
    published_at = CASE WHEN status = '0' THEN COALESCE(update_time, create_time, NOW()) ELSE NULL END;

INSERT INTO page_design_version (
    id, page_design_id, version_no, schema_version, page_name, page_type, page_content,
    publish_remark, publish_by, published_at, create_by, create_time, del_flag, tenant_id
)
SELECT CONCAT('v1_', id), id, 1, 1, page_name, page_type, page_content,
       '历史页面初始化', COALESCE(update_by, create_by), COALESCE(update_time, create_time, NOW()),
       create_by, COALESCE(update_time, create_time, NOW()), '0', tenant_id
FROM page_design
WHERE status = '0' AND del_flag = '0';

UPDATE page_design
SET published_version_id = CONCAT('v1_', id)
WHERE published_status = '1' AND del_flag = '0';

-- ============================================================================
-- 页面装修发布治理与审计
-- Source: db/boot/30page_design_release_audit.sql
-- ============================================================================
-- 商城装修发布治理与审计增量迁移（Boot 单体模式）
-- 目标库：aryn_boot
-- 特性：可重复执行，不执行 DROP/TRUNCATE，不覆盖已有业务数据。
-- 执行：mysql -u root -p aryn_boot < 30page_design_release_audit.sql

USE `aryn_boot`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 页面装修发布申请表
-- 说明：发布流程为 草稿保存 -> 服务端校验 -> 创建 release ->（可配置跳过）审批
-- -> 基于快照生成不可变版本 -> 更新线上指针 -> 记录审计。
-- 申请内容为提交时的页面快照，审批通过后按快照发布，保证审阅内容与上线内容一致。
CREATE TABLE IF NOT EXISTS `page_design_release` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `page_design_id` varchar(32) NOT NULL COMMENT '页面ID（page_design.id）',
  `release_no` int NOT NULL COMMENT '页面内申请序号，从1递增',
  `release_strategy` char(2) NOT NULL DEFAULT '0' COMMENT '发布策略：0.立即；1.定时（预留）；2.灰度（预留）；',
  `release_status` char(2) NOT NULL DEFAULT '0' COMMENT '申请状态：0.待审核；1.已发布；2.已拒绝；3.已取消；',
  `draft_revision` bigint NOT NULL COMMENT '申请时草稿修订号',
  `schema_version` int NOT NULL DEFAULT 2 COMMENT '装修协议版本',
  `page_name` varchar(50) NOT NULL COMMENT '申请时页面名称',
  `page_content` longtext NOT NULL COMMENT '申请内容快照',
  `publish_remark` varchar(255) NULL COMMENT '发布备注',
  `audit_remark` varchar(255) NULL COMMENT '审批意见',
  `submit_by` varchar(60) NULL COMMENT '提交人',
  `submit_at` datetime NULL COMMENT '提交时间',
  `audit_by` varchar(60) NULL COMMENT '审批人',
  `audit_at` datetime NULL COMMENT '审批时间',
  `release_version_id` varchar(32) NULL COMMENT '审批通过后生成的发布版本ID（page_design_version.id）',
  `fail_reason` varchar(255) NULL COMMENT '失败原因（预留）',
  `plan_publish_at` datetime NULL COMMENT '计划发布时间（定时策略预留）',
  `create_by` varchar(60) NULL COMMENT '创建人',
  `update_by` varchar(60) NULL COMMENT '修改人',
  `create_time` datetime NULL COMMENT '创建时间',
  `update_time` datetime NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
  `tenant_id` varchar(32) NOT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_page_design_release_no` (`tenant_id`, `page_design_id`, `release_no`),
  KEY `idx_page_design_release_status` (`page_design_id`, `release_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='页面装修发布申请表';

-- 页面装修审计日志表（追加写，不提供业务更新）
-- 说明：记录草稿保存、发布、下线、回滚与发布申请全流程，
-- 保证任何线上版本可回溯到租户、操作者、release 与前后版本。
CREATE TABLE IF NOT EXISTS `page_design_audit_log` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `page_design_id` varchar(32) NOT NULL COMMENT '页面ID（page_design.id）',
  `release_id` varchar(32) NULL COMMENT '关联发布申请ID（page_design_release.id）',
  `action` varchar(32) NOT NULL COMMENT '操作类型：SAVE_DRAFT/PUBLISH/UNPUBLISH/SET_HOME/ROLLBACK/RELEASE_SUBMIT/RELEASE_APPROVE/RELEASE_REJECT/RELEASE_CANCEL',
  `operator` varchar(60) NULL COMMENT '操作人',
  `operator_ip` varchar(64) NULL COMMENT '操作者IP',
  `before_version_id` varchar(32) NULL COMMENT '操作前发布版本ID',
  `after_version_id` varchar(32) NULL COMMENT '操作后发布版本ID',
  `before_revision` bigint NULL COMMENT '操作前草稿修订号',
  `after_revision` bigint NULL COMMENT '操作后草稿修订号',
  `result` char(2) NOT NULL DEFAULT '0' COMMENT '操作结果：0.成功；1.失败；',
  `remark` varchar(255) NULL COMMENT '备注',
  `create_by` varchar(60) NULL COMMENT '创建人',
  `create_time` datetime NULL COMMENT '创建时间',
  `del_flag` char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
  `tenant_id` varchar(32) NOT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`),
  KEY `idx_page_design_audit_page` (`tenant_id`, `page_design_id`, `create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='页面装修审计日志表';

-- 装修发布治理按钮权限（IGNORE 幂等）
INSERT IGNORE INTO `sys_menu`
  (`id`, `name`, `permission`, `path`, `redirect`, `parent_id`, `icon`, `component`, `sort`, `type`,
   `create_time`, `update_time`, `outer_status`, `del_flag`, `application_key`, `create_by`, `update_by`)
VALUES
