-- ============================================================================
-- 配送员商城账号绑定
-- Source: db/boot/29delivery_account_binding.sql
-- ============================================================================
-- 悦航购配送员商城账号绑定增量迁移（Boot 单体模式）
-- 目标库：aryn_boot
-- 特性：可重复执行，不执行 DROP/TRUNCATE，不覆盖已有业务数据。
-- 执行：mysql -u root -p aryn_boot < 29delivery_account_binding.sql

USE `aryn_boot`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 配送员与商城用户绑定关系表
-- 说明：
-- 1. 同一商城用户在租户内全历史仅一行（唯一键 tenant_id+mall_user_id），
--    解绑通过 status='0' 保留记录，重新绑定时复用该行更新归属。
-- 2. active_sys_user_id 为生成列：仅有效绑定（status='1' 且未删除）取 sys_user_id，
--    配合唯一键 uk_delivery_binding_active_sys_user 在数据库层保证
--    同一员工账号在租户内最多一个有效绑定（解绑行为 NULL，不占用唯一键）。
CREATE TABLE IF NOT EXISTS `delivery_account_binding` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `mall_user_id` varchar(32) NOT NULL COMMENT '商城用户ID（user_info.id）',
  `sys_user_id` varchar(32) NOT NULL COMMENT '员工账号ID（sys_user.id）',
  `delivery_staff_id` varchar(32) NOT NULL COMMENT '配送员资料ID（delivery_staff.id）',
  `status` varchar(2) NOT NULL DEFAULT '1' COMMENT '绑定状态：1有效 0解绑',
  `active_sys_user_id` varchar(32) GENERATED ALWAYS AS (
    CASE WHEN `status` = '1' AND `del_flag` = '0' THEN `sys_user_id` ELSE NULL END
  ) STORED COMMENT '有效绑定员工账号（生成列，供唯一键使用）',
  `bind_time` datetime DEFAULT NULL COMMENT '绑定时间',
  `unbind_time` datetime DEFAULT NULL COMMENT '解绑时间',
  `bind_by` varchar(60) DEFAULT NULL COMMENT '绑定操作人',
  `unbind_by` varchar(60) DEFAULT NULL COMMENT '解绑操作人',
  `tenant_id` varchar(32) NOT NULL COMMENT '租户ID',
  `create_by` varchar(60) DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(60) DEFAULT NULL COMMENT '修改人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_delivery_binding_mall_user` (`tenant_id`, `mall_user_id`),
  UNIQUE KEY `uk_delivery_binding_active_sys_user` (`tenant_id`, `active_sys_user_id`),
  KEY `idx_delivery_binding_sys_user` (`tenant_id`, `sys_user_id`),
  KEY `idx_delivery_binding_staff` (`tenant_id`, `delivery_staff_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='配送员商城账号绑定';

-- 配送员管理新增按钮权限（平台级定义，IGNORE 幂等）
INSERT IGNORE INTO `sys_menu` (`id`, `name`, `permission`, `path`, `redirect`, `parent_id`, `icon`, `component`, `sort`, `type`, `create_time`, `update_time`, `outer_status`, `del_flag`, `application_key`, `create_by`, `update_by`) VALUES
('2100000000000000060', '绑定商城账号', 'delivery:staff:bind', NULL, NULL, '2100000000000000003', '', NULL, 8, '1', NOW(), NULL, '0', '0', 'app_base', 'system', NULL),
('2100000000000000061', '配送资格管理', 'delivery:staff:qualification', NULL, NULL, '2100000000000000003', '', NULL, 9, '1', NOW(), NULL, '0', '0', 'app_base', 'system', NULL),
('2100000000000000062', '接单状态管理', 'delivery:staff:availability', NULL, NULL, '2100000000000000003', '', NULL, 10, '1', NOW(), NULL, '0', '0', 'app_base', 'system', NULL);

-- 配送员执行角色按租户初始化（平台定义 + 存量租户幂等补齐，不写死租户ID）
-- 角色ID = MD5('delivery_staff_role_' + tenant_id)，稳定且租户内唯一；
-- 移动端免重复登录依赖该角色携带 delivery:execute（菜单 2100000000000000017）。
INSERT IGNORE INTO `sys_role` (`id`, `role_name`, `role_code`, `role_desc`, `create_time`, `update_time`, `del_flag`, `tenant_id`, `create_by`)
SELECT MD5(CONCAT('delivery_staff_role_', t.`id`)), '配送员', 'delivery_staff',
       '移动端配送工作台执行角色，仅包含配送执行权限', NOW(), NULL, '0', t.`id`, 'system'
FROM `sys_tenant` t
WHERE t.`del_flag` = '0'
  AND NOT EXISTS (
    SELECT 1 FROM `sys_role` r
    WHERE r.`role_code` = 'delivery_staff' AND r.`tenant_id` = t.`id` AND r.`del_flag` = '0'
  );

-- 配送员角色授予配送执行权限（按角色逐条幂等补齐）
INSERT IGNORE INTO `sys_role_menu` (`id`, `role_id`, `menu_id`, `create_time`, `tenant_id`)
SELECT MD5(CONCAT(r.`id`, ':menu:2100000000000000017')), r.`id`, '2100000000000000017', NOW(), r.`tenant_id`
FROM `sys_role` r
WHERE r.`role_code` = 'delivery_staff' AND r.`del_flag` = '0'
  AND NOT EXISTS (
    SELECT 1 FROM `sys_role_menu` rm
    WHERE rm.`role_id` = r.`id` AND rm.`menu_id` = '2100000000000000017'
  );

-- 新增按钮分配给各租户管理员角色（role_code=ROLE_ADMIN，按租户幂等补齐，不写死租户ID）
INSERT IGNORE INTO `sys_role_menu` (`id`, `role_id`, `menu_id`, `create_time`, `tenant_id`)
SELECT MD5(CONCAT(r.`id`, ':menu:', m.`menu_id`)), r.`id`, m.`menu_id`, NOW(), r.`tenant_id`
FROM `sys_role` r
JOIN (
  SELECT '2100000000000000060' AS menu_id
  UNION ALL SELECT '2100000000000000061'
  UNION ALL SELECT '2100000000000000062'
) m ON 1=1
WHERE r.`role_code` = 'ROLE_ADMIN' AND r.`del_flag` = '0'
  AND NOT EXISTS (
    SELECT 1 FROM `sys_role_menu` rm
    WHERE rm.`role_id` = r.`id` AND rm.`menu_id` = m.`menu_id`
  );

-- 新增按钮按租户初始化租户菜单（不写死租户ID）
INSERT IGNORE INTO `sys_tenant_menu` (`id`, `tenant_id`, `menu_id`, `create_time`, `create_by`)
SELECT MD5(CONCAT(t.`id`, ':menu:', m.`menu_id`)), t.`id`, m.`menu_id`, NOW(), 'system'
FROM `sys_tenant` t
JOIN (
  SELECT '2100000000000000060' AS menu_id
  UNION ALL SELECT '2100000000000000061'
  UNION ALL SELECT '2100000000000000062'
) m ON 1=1
WHERE t.`del_flag` = '0'
  AND NOT EXISTS (
    SELECT 1 FROM `sys_tenant_menu` tm
    WHERE tm.`tenant_id` = t.`id` AND tm.`menu_id` = m.`menu_id`
  );

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================================
-- 配送资格操作补偿记录
-- Source: db/boot/34delivery_qualification_operation.sql
-- ============================================================================
-- 配送资格操作补偿记录表增量迁移（Boot 单体模式）
-- 目标库：aryn_boot
-- 特性：可重复执行，不执行 DROP/TRUNCATE，不覆盖已有业务数据。
-- 执行：mysql -u root -p aryn_boot < 34delivery_qualification_operation.sql

USE `aryn_boot`;
SET NAMES utf8mb4;

-- 配送资格操作（可靠授权/回收记录）
-- 说明：UPMS 角色授予/回收是跨服务远程操作，无法随订单域本地事务回滚。
-- 本表作为 outbox：本地事务提交前写入待处理操作，事务提交后同步执行一次，
-- 失败由补偿任务（DeliveryQualificationRetryJob）按指数退避重试直到成功，
-- 保证不残留孤儿角色或未回收权限。
-- 幂等键 (tenant_id, idempotent_key) 保证同一租户内同一员工同一角色同一操作仅一条记录，
-- 历史记录复用重置，不重复新增。
CREATE TABLE IF NOT EXISTS `delivery_qualification_operation` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `staff_id` varchar(32) NOT NULL COMMENT '配送员资料ID（delivery_staff.id）',
  `sys_user_id` varchar(32) NOT NULL COMMENT '员工账号ID（sys_user.id）',
  `role_code` varchar(64) NOT NULL COMMENT '角色编码',
  `operation` varchar(16) NOT NULL COMMENT '操作类型：GRANT授予 REVOKE回收',
  `status` varchar(16) NOT NULL DEFAULT 'PENDING' COMMENT '状态：PENDING待处理 DONE已完成',
  `idempotent_key` varchar(128) NOT NULL COMMENT '幂等键（operation:sys_user_id:role_code）',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '已执行次数（含失败重试）',
  `last_error` varchar(512) DEFAULT NULL COMMENT '最近一次失败原因',
  `next_retry_time` datetime DEFAULT NULL COMMENT '下次重试时间',
  `tenant_id` varchar(32) NOT NULL COMMENT '租户ID',
  `create_by` varchar(60) DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(60) DEFAULT NULL COMMENT '修改人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_delivery_qual_op_key` (`tenant_id`, `idempotent_key`),
  KEY `idx_delivery_qual_op_retry` (`tenant_id`, `status`, `next_retry_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='配送资格操作补偿记录';

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================================
-- 配送员商城账号绑定结构升级
-- Source: db/boot/35delivery_account_binding_schema_upgrade.sql
-- ============================================================================
-- 配送员商城账号绑定表结构升级增量迁移（Boot 单体模式）
-- 目标库：aryn_boot
-- 背景：29delivery_account_binding.sql 使用 CREATE TABLE IF NOT EXISTS，
--       对已存在旧版 delivery_account_binding（缺少 active_sys_user_id 生成列
--       或唯一索引）的环境不会补齐缺失结构，约束并未生效。
-- 特性：可重复执行，不执行 DROP/TRUNCATE，不覆盖已有业务数据。
-- 前置检查（步骤 1）如返回重复有效绑定，必须先由管理员确认保留记录、
--       通过业务解绑/逻辑删除处理另一条后再执行步骤 2-4，禁止脚本自动删除。
-- 执行：mysql -u root -p aryn_boot < 35delivery_account_binding_schema_upgrade.sql

USE `aryn_boot`;
SET NAMES utf8mb4;

-- 1) 重复有效绑定检查（应返回空结果集；如有返回，先人工处理再继续）
SELECT tenant_id, sys_user_id, COUNT(*) AS cnt
FROM delivery_account_binding
WHERE status = '1' AND del_flag = '0'
GROUP BY tenant_id, sys_user_id
HAVING COUNT(*) > 1;

-- 2) 幂等补齐有效绑定员工账号生成列
SET @ddl = IF(
  (SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'delivery_account_binding'
      AND COLUMN_NAME = 'active_sys_user_id') = 0,
  'ALTER TABLE `delivery_account_binding` ADD COLUMN `active_sys_user_id` varchar(32) GENERATED ALWAYS AS (CASE WHEN `status` = ''1'' AND `del_flag` = ''0'' THEN `sys_user_id` ELSE NULL END) STORED COMMENT ''有效绑定员工账号（生成列，供唯一键使用）''',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 3) 幂等补齐同一员工账号最多一个有效绑定的唯一键
SET @ddl = IF(
  (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'delivery_account_binding'
      AND INDEX_NAME = 'uk_delivery_binding_active_sys_user') = 0,
  'ALTER TABLE `delivery_account_binding` ADD UNIQUE KEY `uk_delivery_binding_active_sys_user` (`tenant_id`, `active_sys_user_id`)',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 4) 幂等补齐辅助索引（旧版本表可能缺失）
SET @ddl = IF(
  (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'delivery_account_binding'
      AND INDEX_NAME = 'idx_delivery_binding_sys_user') = 0,
  'ALTER TABLE `delivery_account_binding` ADD KEY `idx_delivery_binding_sys_user` (`tenant_id`, `sys_user_id`)',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @ddl = IF(
  (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'delivery_account_binding'
      AND INDEX_NAME = 'idx_delivery_binding_staff') = 0,
  'ALTER TABLE `delivery_account_binding` ADD KEY `idx_delivery_binding_staff` (`tenant_id`, `delivery_staff_id`)',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================================
-- 用户角色关联逻辑删除改造
-- Source: db/boot/36sys_user_role_logic_delete.sql
-- ============================================================================
-- 用户角色关联（sys_user_role）逻辑删除改造增量迁移（Boot 单体模式）
-- 目标库：aryn_boot
-- 背景：项目规则要求逻辑删除，sys_user_role 原先仅物理删除；
--       本脚本补齐 del_flag/update_time/update_by 与有效关联唯一约束，
--       配合 SysUserRole @TableLogic 使回收角色改为逻辑删除并可审计。
-- 特性：可重复执行，不执行 DROP/TRUNCATE，不覆盖已有业务数据。
-- 前置检查（步骤 1）如返回重复有效关联，必须先人工确认保留一条、
--       处理其余后（建议保留行 del_flag='0'，其余置为 '1'）再执行步骤 4，
--       禁止脚本自动删除。
-- 执行：mysql -u root -p aryn_boot < 36sys_user_role_logic_delete.sql

USE `aryn_boot`;
SET NAMES utf8mb4;

-- 1) 重复有效关联检查（应返回空结果集；如有返回，先人工处理再继续步骤 4）
SELECT tenant_id, user_id, role_id, COUNT(*) AS cnt
FROM sys_user_role
GROUP BY tenant_id, user_id, role_id
HAVING COUNT(*) > 1;

-- 2) 幂等补齐逻辑删除标记
SET @ddl = IF(
  (SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'sys_user_role'
      AND COLUMN_NAME = 'del_flag') = 0,
  'ALTER TABLE `sys_user_role` ADD COLUMN `del_flag` char(2) NOT NULL DEFAULT ''0'' COMMENT ''逻辑删除：0.显示；1.隐藏；''',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 3) 幂等补齐审计字段
SET @ddl = IF(
  (SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'sys_user_role'
      AND COLUMN_NAME = 'update_time') = 0,
  'ALTER TABLE `sys_user_role` ADD COLUMN `update_time` datetime DEFAULT NULL COMMENT ''修改时间''',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @ddl = IF(
  (SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'sys_user_role'
      AND COLUMN_NAME = 'update_by') = 0,
  'ALTER TABLE `sys_user_role` ADD COLUMN `update_by` varchar(60) DEFAULT NULL COMMENT ''修改人''',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 4) 幂等补齐有效关联生成列与唯一键：
--    active_user_id 仅在 del_flag='0' 时取 user_id，回收行不占用唯一键，
--    数据库层保证同一租户内 (role_id, user_id) 最多一条有效关联。
SET @ddl = IF(
  (SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'sys_user_role'
      AND COLUMN_NAME = 'active_user_id') = 0,
  'ALTER TABLE `sys_user_role` ADD COLUMN `active_user_id` varchar(32) GENERATED ALWAYS AS (CASE WHEN `del_flag` = ''0'' THEN `user_id` ELSE NULL END) STORED COMMENT ''有效关联用户ID（生成列，供唯一键使用）''',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @ddl = IF(
  (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'sys_user_role'
      AND INDEX_NAME = 'uk_sys_user_role_active') = 0,
  'ALTER TABLE `sys_user_role` ADD UNIQUE KEY `uk_sys_user_role_active` (`tenant_id`, `role_id`, `active_user_id`)',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================================
-- 员工账号与配送员管理重构
-- Source: db/boot/37employee_role_scope.sql
-- ============================================================================
-- 员工账号与配送员管理重构增量迁移（Boot 单体模式）
-- 目标库：aryn_boot
-- 背景：
--   1) delivery_staff（配送员）为受保护角色，只能由配送员管理（资格接口/向导）授予或回收，
--      通用“新增/修改员工账号”接口不再接受该角色；为避免管理员被迫选择超级管理员，
--      幂等补齐每个租户的最低权限员工角色“普通员工”（ROLE_STAFF）。
--   2) 系统设置菜单“用户管理”更名为“员工账号”，路由 /system/user 与权限编码保持不变。
--   3) 输出重复角色与配送资格历史异常数据的预检查结果，供管理员确认后人工迁移；
--      仅在不存在重复角色编码时补齐 (tenant_id, role_code) 唯一约束。
-- 特性：可重复执行，不执行 DROP/TRUNCATE，不物理删除存量数据。
-- 执行：mysql -u root -p aryn_boot < 37employee_role_scope.sql

USE `aryn_boot`;
SET NAMES utf8mb4;

-- 1) 预检查 1：同一租户同一角色编码的重复有效角色（应返回空结果集；
--    如有返回，请人工保留一条稳定角色ID，其余角色的菜单/用户关联逻辑迁移后置 del_flag='1'，
--    禁止脚本自动删除；清理完成后重跑本脚本即可补齐唯一约束）
SELECT tenant_id, role_code, COUNT(*) AS cnt
FROM sys_role
WHERE del_flag = '0'
GROUP BY tenant_id, role_code
HAVING COUNT(*) > 1;

-- 2) 预检查 2：拥有配送员角色但没有配送员资料的员工账号（历史半成品数据，应返回空结果集；
--    如有返回，请在配送员管理中补建配送资料，或确认后回收配送资格）
SELECT sur.tenant_id, sur.user_id, su.username, su.nickname
FROM sys_user_role sur
INNER JOIN sys_role sr
        ON sr.id = sur.role_id
       AND sr.del_flag = '0'
       AND sr.role_code = 'delivery_staff'
INNER JOIN sys_user su
        ON su.id = sur.user_id
       AND su.del_flag = '0'
WHERE sur.del_flag = '0'
  AND NOT EXISTS (SELECT 1
                  FROM delivery_staff ds
                  WHERE ds.user_id = sur.user_id
                    AND ds.del_flag = '0');

-- 3) 预检查 3：迁移台账（受影响租户与角色统计，供上线记录留存）
SELECT sr.tenant_id, sr.role_code, sr.role_name, COUNT(sur.id) AS user_count
FROM sys_role sr
LEFT JOIN sys_user_role sur
       ON sur.role_id = sr.id
      AND sur.del_flag = '0'
WHERE sr.del_flag = '0'
  AND sr.role_code IN ('delivery_staff', 'ROLE_STAFF')
GROUP BY sr.tenant_id, sr.role_code, sr.role_name;

-- 4) 幂等补齐每个租户的最低权限员工角色“普通员工”（ROLE_STAFF）：
--    覆盖 sys_tenant 登记租户与 sys_user 中实际存在的租户，已存在（含逻辑删除后恢复）不重复插入
INSERT INTO sys_role (id, role_name, role_code, role_desc, create_time, del_flag, tenant_id, create_by)
SELECT REPLACE(UUID(), '-', ''), '普通员工', 'ROLE_STAFF',
       '最低权限员工角色：满足员工账号基础角色要求，不含配送资格与管理菜单',
       NOW(), '0', t.tenant_id, 'system'
FROM (
    SELECT id AS tenant_id FROM sys_tenant WHERE del_flag = '0'
    UNION
    SELECT DISTINCT tenant_id FROM sys_user WHERE del_flag = '0' AND tenant_id IS NOT NULL
) t
WHERE NOT EXISTS (
    SELECT 1 FROM sys_role r
    WHERE r.tenant_id = t.tenant_id
      AND r.role_code = 'ROLE_STAFF'
      AND r.del_flag = '0'
);

-- 5) 幂等菜单更名：用户管理 -> 员工账号（路由与权限编码不变）
UPDATE sys_menu
SET name = '员工账号', update_time = NOW(), update_by = 'system'
WHERE id = '1491752531735490561'
  AND name = '用户管理';

-- 6) 幂等补齐有效角色编码生成列（逻辑删除行不占用唯一键）
SET @ddl = IF(
  (SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'sys_role'
      AND COLUMN_NAME = 'active_role_code') = 0,
  'ALTER TABLE `sys_role` ADD COLUMN `active_role_code` varchar(50) GENERATED ALWAYS AS (CASE WHEN `del_flag` = ''0'' THEN `role_code` ELSE NULL END) STORED COMMENT ''有效角色编码（生成列，供唯一键使用）''',
  'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 7) 仅在当前不存在重复角色编码时补齐唯一约束；存在重复（预检查 1 有结果）时跳过并提示，
--    待人工迁移完成后重跑本脚本
SET @dup_count = (
  SELECT COUNT(*) FROM (
    SELECT tenant_id, role_code
    FROM sys_role
    WHERE del_flag = '0'
    GROUP BY tenant_id, role_code
    HAVING COUNT(*) > 1
  ) d);
SET @ddl = IF(
  @dup_count = 0
  AND (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'sys_role'
      AND INDEX_NAME = 'uk_sys_role_tenant_code') = 0,
  'ALTER TABLE `sys_role` ADD UNIQUE KEY `uk_sys_role_tenant_code` (`tenant_id`, `active_role_code`)',
  'SELECT ''存在重复角色编码或约束已存在，跳过唯一约束创建（见预检查 1）'' AS migrate_notice');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================================
-- 字典与菜单乱码数据修复
-- Source: db/boot/38dict_charset_mojibake_repair.sql
-- ============================================================================
-- 字典与菜单乱码数据修复（Boot 单体模式）
-- 目标库：aryn_boot
-- 背景：历史增量脚本曾以 latin1/cp1252 客户端字符集导入，UTF-8 文本被双重编码，
--       界面出现「é˜¿é‡ŒOSS」「ä¸ƒç‰›äº‘」等乱码，涉及：存储配置类型字典、
--       商品品牌/仓库配置菜单按钮、页面装修发布备注。
-- 原理：MySQL latin1 与 CP1252 同语义，先把存储值还原回原始字节，再按 utf8mb4 解读。
-- 特性：可重复执行；仅命中含乱码特征（ÃÂäåæçèé 开头字节）的行，还原失败时保留原值，
--       正常中文与英文数据不受影响。
-- 执行：mysql -u root -p --default-character-set=utf8mb4 aryn_boot < 38dict_charset_mojibake_repair.sql
-- 验证：SELECT dict_label FROM sys_dict_value WHERE dict_type='sys_storage_type';

USE `aryn_boot`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1) 字典值标签与备注（存储配置类型：阿里OSS/七牛云/腾讯云/MinIO/本机存储）
UPDATE `sys_dict_value`
JOIN (
    SELECT `id`,
           CONVERT(BINARY CONVERT(`dict_label` USING latin1) USING utf8mb4) AS fixed_label,
           CONVERT(BINARY CONVERT(`remarks` USING latin1) USING utf8mb4) AS fixed_remarks
    FROM `sys_dict_value`
    WHERE `dict_label` REGEXP _utf8mb4 0x5BC383C282C3A4C3A5C3A6C3A7C3A8C3A95D
       OR `remarks` REGEXP _utf8mb4 0x5BC383C282C3A4C3A5C3A6C3A7C3A8C3A95D
) t ON t.`id` = `sys_dict_value`.`id`
SET `sys_dict_value`.`dict_label` = COALESCE(t.fixed_label, `sys_dict_value`.`dict_label`),
    `sys_dict_value`.`remarks` = COALESCE(t.fixed_remarks, `sys_dict_value`.`remarks`);

-- 2) 菜单名称（商品品牌列表/查询/新增/修改/删除、查看/保存仓库配置等）
UPDATE `sys_menu`
JOIN (
    SELECT `id`,
           CONVERT(BINARY CONVERT(`name` USING latin1) USING utf8mb4) AS fixed_name
    FROM `sys_menu`
    WHERE `name` REGEXP _utf8mb4 0x5BC383C282C3A4C3A5C3A6C3A7C3A8C3A95D
) t ON t.`id` = `sys_menu`.`id`
SET `sys_menu`.`name` = COALESCE(t.fixed_name, `sys_menu`.`name`);

-- 3) 页面装修发布备注
UPDATE `page_design_version`
JOIN (
    SELECT `id`,
           CONVERT(BINARY CONVERT(`publish_remark` USING latin1) USING utf8mb4) AS fixed_remark
    FROM `page_design_version`
    WHERE `publish_remark` REGEXP _utf8mb4 0x5BC383C282C3A4C3A5C3A6C3A7C3A8C3A95D
) t ON t.`id` = `page_design_version`.`id`
SET `page_design_version`.`publish_remark` = COALESCE(t.fixed_remark, `page_design_version`.`publish_remark`);

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================================
-- 配送模块按钮权限补齐
-- Source: db/boot/39delivery_menu_button_patch.sql
-- ============================================================================
-- ============================================================================
-- 配送模块按钮权限补齐
-- 背景: 09174b7 将配送员详情/列表/状态与出车单详情四个按钮权限补入 27 号增量
--       脚本，但已按旧版执行过 27 号脚本的环境不会重跑，导致编辑配送员、
--       出车单详情等读接口报"无此权限: delivery:staff:get"。
-- 行为: 按固定 ID 幂等补齐 sys_menu 四个按钮行；并向已拥有同父菜单任一按钮
--       授权的角色与租户推导式补授，重复执行无副作用。
-- ============================================================================

SET FOREIGN_KEY_CHECKS = 0;

INSERT IGNORE INTO `sys_menu` (`id`,`name`,`permission`,`path`,`redirect`,`parent_id`,`icon`,`component`,`sort`,`type`,`create_time`,`outer_status`,`del_flag`,`application_key`,`create_by`) VALUES
('2100000000000000024','配送员详情','delivery:staff:get',NULL,NULL,'2100000000000000003','',NULL,5,'1',NOW(),'0','0','app_base','system'),
('2100000000000000025','配送员列表','delivery:staff:list',NULL,NULL,'2100000000000000003','',NULL,6,'1',NOW(),'0','0','app_base','system'),
('2100000000000000026','配送员状态','delivery:staff:status',NULL,NULL,'2100000000000000003','',NULL,7,'1',NOW(),'0','0','app_base','system'),
('2100000000000000027','出车单详情','delivery:trip:get',NULL,NULL,'2100000000000000004','',NULL,2,'1',NOW(),'0','0','app_base','system');

-- 向已拥有同父菜单任一按钮授权的角色补授新按钮，主键用 MD5(role_id:menu:menu_id) 保证幂等。
INSERT IGNORE INTO `sys_role_menu` (`id`,`role_id`,`menu_id`,`create_time`,`tenant_id`)
SELECT MD5(CONCAT(gr.`role_id`, ':menu:', m.`id`)), gr.`role_id`, m.`id`, NOW(), gr.`tenant_id`
FROM `sys_menu` m
JOIN `sys_menu` peer ON peer.`parent_id` = m.`parent_id` AND peer.`del_flag` = '0'
JOIN `sys_role_menu` gr ON gr.`menu_id` = peer.`id`
WHERE m.`id` IN ('2100000000000000024','2100000000000000025','2100000000000000026','2100000000000000027')
  AND m.`del_flag` = '0';

-- 向已开通同父菜单的租户补齐租户菜单记录。
INSERT IGNORE INTO `sys_tenant_menu` (`id`,`tenant_id`,`menu_id`,`create_time`,`create_by`)
SELECT MD5(CONCAT(gt.`tenant_id`, ':menu:', m.`id`)), gt.`tenant_id`, m.`id`, NOW(), 'system'
FROM `sys_menu` m
JOIN `sys_menu` peer ON peer.`parent_id` = m.`parent_id` AND peer.`del_flag` = '0'
JOIN `sys_tenant_menu` gt ON gt.`menu_id` = peer.`id`
WHERE m.`id` IN ('2100000000000000024','2100000000000000025','2100000000000000026','2100000000000000027')
  AND m.`del_flag` = '0';

SET FOREIGN_KEY_CHECKS = 1;

-- 执行结果自检：应返回 4 行菜单与对应的角色/租户授权。
SELECT m.`id`, m.`permission`,
       (SELECT COUNT(*) FROM `sys_role_menu` rm WHERE rm.`menu_id` = m.`id`) AS role_grants,
       (SELECT COUNT(*) FROM `sys_tenant_menu` tm WHERE tm.`menu_id` = m.`id`) AS tenant_grants
FROM `sys_menu` m
WHERE m.`id` IN ('2100000000000000024','2100000000000000025','2100000000000000026','2100000000000000027');

-- ============================================================================
-- 配送员受保护角色修复与遗留角色下线
-- Source: db/boot/40delivery_staff_role_repair.sql
-- ============================================================================
-- 配送员受保护角色修复与遗留角色下线增量迁移（Boot 单体模式）
-- 目标库：aryn_boot
-- 背景：
--   1) 29 号脚本按租户种子 delivery_staff（配送员）角色时，若该角色事后在角色管理中被
--      逻辑删除，重跑 29 号会因主键 MD5('delivery_staff_role_'+tenant_id) 冲突被
--      INSERT IGNORE 静默跳过，角色无法自愈；配送员管理开通/停用资格即报
--      “未找到编码为 delivery_staff 的角色，请先在角色管理中创建”。
--      本脚本幂等恢复被逻辑删除的受保护角色，并补挂配送执行权限菜单
--      （delivery:execute，菜单 2100000000000000017）。
--   2) 老版配送模块遗留角色 ROLE_DELIVERY_STAFF（与受保护角色同名“配送员”）在现行代码中
--      已无任何引用，同名并存曾在角色管理中造成误删受保护角色，按逻辑删除下线；
--      其用户绑定与角色菜单关联保留作历史，权限计算只关联有效角色，不受影响。
--      不迁移其用户绑定：配送资格在新体系下只能经配送员管理开通（fail-closed），
--      自动改绑等价于越权开通。
--   3) 配套后端防护：角色管理删除受保护角色、或修改其角色编码会被拒绝
--      （SysRoleController，CommonConstants.PROTECTED_DELIVERY_ROLE_CODE）。
-- 特性：可重复执行，不执行 DROP/TRUNCATE，不物理删除存量数据。
-- 执行：mysql -u root -p aryn_boot < 40delivery_staff_role_repair.sql

USE `aryn_boot`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1) 预检查 1：受保护配送员角色现状（每租户应恰一行有效；del_flag=1 即待修复对象）
SELECT tenant_id, id, role_name, del_flag, update_time, update_by
FROM sys_role
WHERE role_code = 'delivery_staff'
ORDER BY tenant_id, del_flag;

-- 2) 预检查 2：遗留同名配送员角色及其有效用户绑定台账（下线前留档，应只有历史意义）
SELECT sr.tenant_id, sr.id AS role_id, sr.del_flag, COUNT(sur.id) AS bound_users
FROM sys_role sr
LEFT JOIN sys_user_role sur ON sur.role_id = sr.id AND sur.del_flag = '0'
WHERE sr.role_code = 'ROLE_DELIVERY_STAFF'
GROUP BY sr.tenant_id, sr.id, sr.del_flag;

-- 3) 幂等恢复被逻辑删除的 delivery_staff：仅当该租户不存在有效 delivery_staff 角色时，
--    每租户恢复一行（取 MAX(id)，避免多行删除数据触发有效编码唯一键冲突）；
--    保留原角色ID，历史绑定与资格操作日志的 role 引用不断裂
UPDATE sys_role sr
JOIN (
    SELECT MAX(r.id) AS id
    FROM sys_role r
    WHERE r.role_code = 'delivery_staff'
      AND r.del_flag = '1'
      AND NOT EXISTS (
          SELECT 1 FROM sys_role ok
          WHERE ok.tenant_id = r.tenant_id
            AND ok.role_code = 'delivery_staff'
            AND ok.del_flag = '0')
    GROUP BY r.tenant_id
) todo ON todo.id = sr.id
SET sr.del_flag = '0', sr.update_time = NOW(), sr.update_by = 'system';

-- 4) 幂等补齐从未有过 delivery_staff 的租户（与 29 号同构：角色ID = MD5('delivery_staff_role_'+tenant_id)；
--    覆盖 sys_tenant 登记租户与 sys_user 实际租户；NOT EXISTS 不过滤 del_flag，
--    与步骤 3 的恢复逻辑互补，任何存量行（含已删除）都不会重复插入）
INSERT INTO sys_role (id, role_name, role_code, role_desc, create_time, del_flag, tenant_id, create_by)
SELECT MD5(CONCAT('delivery_staff_role_', t.tenant_id)), '配送员', 'delivery_staff',
       '移动端配送工作台执行角色，仅包含配送执行权限', NOW(), '0', t.tenant_id, 'system'
FROM (
    SELECT id AS tenant_id FROM sys_tenant WHERE del_flag = '0'
    UNION
    SELECT DISTINCT tenant_id FROM sys_user WHERE del_flag = '0' AND tenant_id IS NOT NULL
) t
WHERE NOT EXISTS (
    SELECT 1 FROM sys_role r
    WHERE r.tenant_id = t.tenant_id
      AND r.role_code = 'delivery_staff'
);

-- 5) 幂等补挂配送执行权限（delivery:execute，菜单 2100000000000000017）：
--    角色管理删除角色时会连带清空 sys_role_menu，恢复角色后必须补回
INSERT IGNORE INTO sys_role_menu (id, role_id, menu_id, create_time, tenant_id)
SELECT MD5(CONCAT(r.id, ':menu:2100000000000000017')), r.id, '2100000000000000017', NOW(), r.tenant_id
FROM sys_role r
WHERE r.role_code = 'delivery_staff' AND r.del_flag = '0'
  AND NOT EXISTS (
    SELECT 1 FROM sys_role_menu rm
    WHERE rm.role_id = r.id AND rm.menu_id = '2100000000000000017');

-- 6) 下线遗留同名配送员角色 ROLE_DELIVERY_STAFF（逻辑删除；现行代码零引用）
UPDATE sys_role
SET del_flag = '1', update_time = NOW(), update_by = 'system'
WHERE role_code = 'ROLE_DELIVERY_STAFF' AND del_flag = '0';

-- 7) 结果核验：每租户应恰一行有效 delivery_staff 且已挂配送执行菜单；ROLE_DELIVERY_STAFF 应全部 del_flag=1
SELECT sr.tenant_id, sr.role_code, sr.id, sr.del_flag,
       (SELECT COUNT(*) FROM sys_role_menu rm
         WHERE rm.role_id = sr.id AND rm.menu_id = '2100000000000000017') AS has_execute_menu
FROM sys_role sr
WHERE sr.role_code IN ('delivery_staff', 'ROLE_DELIVERY_STAFF')
ORDER BY sr.role_code, sr.tenant_id;

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================================
-- 船舶与靠港计划域
-- Source: db/boot/42vessel_context_incremental.sql
-- ============================================================================
-- 悦航购船舶与靠港计划域增量迁移（Boot 单体模式）
-- 目标库：aryn_boot
-- 特性：可重复执行，不执行 DROP/TRUNCATE，不覆盖已有业务数据。
-- 执行：mysql -u root -p aryn_boot < 42vessel_context_incremental.sql

USE `aryn_boot`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 船舶档案
CREATE TABLE IF NOT EXISTS `vessel_info` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `vessel_name` varchar(128) NOT NULL COMMENT '船舶中文名称',
  `vessel_name_en` varchar(255) DEFAULT NULL COMMENT '船舶英文名称',
  `imo_code` varchar(32) DEFAULT NULL COMMENT 'IMO 编号',
  `call_sign` varchar(32) DEFAULT NULL COMMENT '呼号',
  `vessel_type` char(2) DEFAULT NULL COMMENT '船舶类型：1集装箱 2散货 3油轮 4杂货 5其他',
  `flag_state` varchar(64) DEFAULT NULL COMMENT '船旗国',
  `dwt` decimal(12,2) DEFAULT NULL COMMENT '载重吨',
  `crew_capacity` int DEFAULT NULL COMMENT '船员定员',
  `status` char(2) NOT NULL DEFAULT '1' COMMENT '状态：1在营 0停用',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(32) NOT NULL COMMENT '租户ID',
  `create_by` varchar(60) DEFAULT NULL COMMENT '创建人', `update_by` varchar(60) DEFAULT NULL COMMENT '修改人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间', `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_vessel_info_imo` (`tenant_id`,`imo_code`),
  KEY `idx_vessel_info_name` (`tenant_id`,`vessel_name`),
  KEY `idx_vessel_info_status` (`tenant_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='船舶档案';

-- 船舶成员（商城用户与船舶的绑定关系）
CREATE TABLE IF NOT EXISTS `vessel_member` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `vessel_id` varchar(32) NOT NULL COMMENT '船舶ID',
  `user_id` varchar(32) NOT NULL COMMENT '商城用户ID',
  `member_role` char(2) NOT NULL DEFAULT '2' COMMENT '成员角色：1发起人/船长授权 2普通船员 3采购确认人',
  `can_edit` char(2) NOT NULL DEFAULT '1' COMMENT '可编辑共享购物车：1是 0否',
  `can_confirm` char(2) NOT NULL DEFAULT '0' COMMENT '可确认提交订单：1是 0否',
  `status` char(2) NOT NULL DEFAULT '1' COMMENT '在船状态：1在船 0离船',
  `join_time` datetime DEFAULT NULL COMMENT '加入时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(32) NOT NULL COMMENT '租户ID',
  `create_by` varchar(60) DEFAULT NULL COMMENT '创建人', `update_by` varchar(60) DEFAULT NULL COMMENT '修改人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间', `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_vessel_member_unique` (`tenant_id`,`vessel_id`,`user_id`),
  KEY `idx_vessel_member_user` (`tenant_id`,`user_id`),
  KEY `idx_vessel_member_vessel` (`tenant_id`,`vessel_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='船舶成员';

-- 靠港计划
CREATE TABLE IF NOT EXISTS `vessel_call` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `vessel_id` varchar(32) NOT NULL COMMENT '船舶ID',
  `port_code` varchar(32) NOT NULL COMMENT '港口编码',
  `port_name` varchar(128) NOT NULL COMMENT '港口名称',
  `berth` varchar(128) DEFAULT NULL COMMENT '泊位',
  `eta` datetime NOT NULL COMMENT '预计到港时间',
  `etd` datetime NOT NULL COMMENT '预计离港时间',
  `delivery_window_start` datetime DEFAULT NULL COMMENT '配送时间窗开始',
  `delivery_window_end` datetime DEFAULT NULL COMMENT '配送时间窗结束',
  `status` char(2) NOT NULL DEFAULT '1' COMMENT '靠港状态：1计划中 2靠泊中 3已完成 4已取消',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(32) NOT NULL COMMENT '租户ID',
  `create_by` varchar(60) DEFAULT NULL COMMENT '创建人', `update_by` varchar(60) DEFAULT NULL COMMENT '修改人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间', `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
  PRIMARY KEY (`id`),
  KEY `idx_vessel_call_vessel_eta` (`tenant_id`,`vessel_id`,`eta`),
  KEY `idx_vessel_call_port_eta` (`tenant_id`,`port_code`,`eta`),
  KEY `idx_vessel_call_status` (`tenant_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='靠港计划';

SET FOREIGN_KEY_CHECKS = 1;

