    'ALTER TABLE `shopping_cart` ADD COLUMN `active_row_key` varchar(96) GENERATED ALWAYS AS (CASE WHEN `del_flag` = ''0'' THEN CONCAT(`sku_id`, '':'', IFNULL(`vessel_call_id`, '''')) ELSE NULL END) STORED COMMENT ''有效行唯一键（sku+靠港）''',
    'SELECT 1')
