-- ============================================================================
-- 补给单Excel导入
-- Source: db/boot/80shared_cart_import_incremental.sql
-- ============================================================================
-- 补给单 Excel 导入（Boot 单体模式）
--
-- 目标库：aryn_boot
-- 特性：可重复执行；不 DROP/TRUNCATE；不覆盖已有业务数据；仅新增两张表与索引。
--
-- 背景（2026-09-22 · B 版原型「详情 → 导入 → 报告」三步）：
--   船员把线下 Excel 补给清单（编码/品名/规格/数量/单位/备注）一次性导入补给单，
--   服务端按「商品编码优先、品名+规格兜底」匹配 SKU，产出四类结果报告
--   （匹配成功 / 未匹配 / 规格变更 / 超库存，外加原型未画但必然出现的数量异常），
--   未匹配行由操作者人工补选，确认后并入 shared_cart_item。
--
--   与管理端 product_import_job / product_import_row 的区别：那是**商品主数据导入**
--   （新增/更新 goods_spu、goods_sku），本表是**补给清单导入**（写 shared_cart_item），
--   两者字段、校验、落库目标都不同，不能互相复用。
--
-- 语义约定：
--   import.status     1待确认（已解析出报告） 2已并入（明细已写进补给单） 3已取消
--   row.result_type   OK匹配成功 / UNMATCHED未匹配 / SPEC_CHANGED规格变更 /
--                     OVER_STOCK超库存 / INVALID_QTY数量异常 / OFF_SHELF已下架
--   row.resolved_action  ACCEPT_SPEC确认新规格 / ADJUST_QTY调整数量 /
--                        REPLACE_SKU人工补选 / SKIP跳过（null=未处置，确认时按跳过处理）
--   数量口径：planned_quantity = Excel 里的数量，行确认后 requested_quantity 同口径写入；
--             不参与 conversion_rate 换算（全仓无引用，库存按 sku.stock 直比）。
--
-- 执行：mysql -u root -p aryn_boot < 80shared_cart_import_incremental.sql

USE `aryn_boot`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------------------------------------------------------------------------
-- 一、导入任务（一次上传 = 一个任务，报告可反复取回）
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `shared_cart_import` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `cart_id` varchar(32) NOT NULL COMMENT '共享购物车ID',
  `file_name` varchar(255) DEFAULT NULL COMMENT '上传文件名',
  `file_size` bigint DEFAULT NULL COMMENT '文件字节数',
  `file_sha256` char(64) DEFAULT NULL COMMENT '文件内容摘要（重复上传提示用）',
  `total_rows` int NOT NULL DEFAULT 0 COMMENT '解析出的数据行数（不含表头）',
  `matched_rows` int NOT NULL DEFAULT 0 COMMENT '匹配成功行数',
  `unmatched_rows` int NOT NULL DEFAULT 0 COMMENT '未匹配行数',
  `spec_changed_rows` int NOT NULL DEFAULT 0 COMMENT '规格变更行数',
  `over_stock_rows` int NOT NULL DEFAULT 0 COMMENT '超库存行数',
  `invalid_rows` int NOT NULL DEFAULT 0 COMMENT '数量/格式异常行数',
  `off_shelf_rows` int NOT NULL DEFAULT 0 COMMENT '已下架商品行数',
  `imported_rows` int NOT NULL DEFAULT 0 COMMENT '确认后实际并入的明细项数（按 SKU 合并后）',
  `skipped_rows` int NOT NULL DEFAULT 0 COMMENT '确认时跳过或未处置的行数',
  `status` char(2) NOT NULL DEFAULT '1' COMMENT '状态：1待确认 2已并入 3已取消',
  `operator_user_id` varchar(32) NOT NULL COMMENT '上传并确认导入的成员ID',
  `confirmed_time` datetime DEFAULT NULL COMMENT '并入补给单时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(32) NOT NULL COMMENT '租户ID',
  `create_by` varchar(60) DEFAULT NULL COMMENT '创建人', `update_by` varchar(60) DEFAULT NULL COMMENT '修改人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间', `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
  PRIMARY KEY (`id`),
  KEY `idx_shared_cart_import_cart` (`tenant_id`,`cart_id`,`create_time`),
  KEY `idx_shared_cart_import_status` (`tenant_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='补给单Excel导入任务';

-- ---------------------------------------------------------------------------
-- 二、导入解析行（服务端落库，确认时按行处置重新校验，不信任客户端回传内容）
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `shared_cart_import_row` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `import_id` varchar(32) NOT NULL COMMENT '导入任务ID',
  `cart_id` varchar(32) NOT NULL COMMENT '共享购物车ID',
  `row_no` int NOT NULL DEFAULT 0 COMMENT '行号（从1开始，不含表头）',
  `raw_code` varchar(64) DEFAULT NULL COMMENT 'Excel 商品编码原文',
  `raw_name` varchar(255) DEFAULT NULL COMMENT 'Excel 品名原文',
  `raw_spec` varchar(128) DEFAULT NULL COMMENT 'Excel 规格原文',
  `raw_quantity` int DEFAULT NULL COMMENT 'Excel 数量原文',
  `raw_unit` varchar(32) DEFAULT NULL COMMENT 'Excel 单位原文',
  `raw_remark` varchar(255) DEFAULT NULL COMMENT 'Excel 备注原文',
  `match_type` varchar(16) DEFAULT NULL COMMENT '匹配方式：CODE编码 / NAME品名 / AMBIGUOUS多规格待选 / NONE未命中',
  `matched_sku_id` varchar(32) DEFAULT NULL COMMENT '匹配到的SKU ID',
  `matched_spu_id` varchar(32) DEFAULT NULL COMMENT '匹配到的SPU ID',
  `matched_name` varchar(255) DEFAULT NULL COMMENT '匹配到的商品名',
  `matched_spec` varchar(255) DEFAULT NULL COMMENT '匹配到的规格描述',
  `matched_unit` varchar(32) DEFAULT NULL COMMENT '匹配到的采购单位',
  `matched_price` decimal(10,2) DEFAULT NULL COMMENT '匹配时的售价快照（仅展示）',
  `matched_stock` int DEFAULT NULL COMMENT '匹配时的库存快照（仅展示）',
  `planned_quantity` int DEFAULT NULL COMMENT '本次计划采购量（确认后写入 shared_cart_item）',
  `suggested_quantity` int DEFAULT NULL COMMENT '服务端建议数量（超库存调减/数量异常就近取整）',
  `result_type` varchar(24) NOT NULL DEFAULT 'UNMATCHED' COMMENT '结果：OK/UNMATCHED/SPEC_CHANGED/OVER_STOCK/INVALID_QTY/OFF_SHELF',
  `result_message` varchar(500) DEFAULT NULL COMMENT '结果说明（给用户看）',
  `resolved_action` varchar(24) DEFAULT NULL COMMENT '用户处置：ACCEPT_SPEC/ADJUST_QTY/REPLACE_SKU/SKIP',
  `resolved_sku_id` varchar(32) DEFAULT NULL COMMENT '人工补选后的SKU ID',
  `resolved_quantity` int DEFAULT NULL COMMENT '调整后的数量',
  `resolved_time` datetime DEFAULT NULL COMMENT '处置时间',
  `tenant_id` varchar(32) NOT NULL COMMENT '租户ID',
  `create_by` varchar(60) DEFAULT NULL COMMENT '创建人', `update_by` varchar(60) DEFAULT NULL COMMENT '修改人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间', `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(2) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0.显示；1.隐藏；',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_shared_cart_import_row` (`tenant_id`,`import_id`,`row_no`),
  KEY `idx_shared_cart_import_row_cart` (`tenant_id`,`cart_id`),
  KEY `idx_shared_cart_import_row_result` (`tenant_id`,`import_id`,`result_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='补给单Excel导入解析行';

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================================
-- 页面装修审计动作枚举补充
-- Source: db/boot/81page_design_audit_action_comment.sql
-- ============================================================================
-- 页面装修审计动作枚举补充（Boot 单体模式）
-- 目标库：aryn_boot
-- 背景：新增「设为首页」动作（page_design_audit_log.action = 'SET_HOME'，见
--       PageDesignServiceImpl#setAsHome）。该列原为 varchar(32) 枚举注释形式，
--       SQL 层只做注释同步，列类型/长度/可空性保持不变，因此不涉及数据改写。
-- 特性：可重复执行，不执行 DROP/TRUNCATE，不覆盖已有业务数据。
-- 执行：mysql -u root -p aryn_boot < 81page_design_audit_action_comment.sql

USE `aryn_boot`;

SET NAMES utf8mb4;

-- 幂等同步 action 列注释（column 不存在时跳过，避免在旧库上报错）
SET @comment_ddl = IF(
  (SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'page_design_audit_log'
      AND COLUMN_NAME = 'action') = 1,
  'ALTER TABLE `page_design_audit_log` MODIFY COLUMN `action` varchar(32) NOT NULL COMMENT ''操作类型：SAVE_DRAFT/PUBLISH/UNPUBLISH/SET_HOME/ROLLBACK/RELEASE_SUBMIT/RELEASE_APPROVE/RELEASE_REJECT/RELEASE_CANCEL''',
  'SELECT 1');
PREPARE stmt FROM @comment_ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- ============================================================================
-- 优惠券领取记录索引补充
-- Source: db/boot/82coupon_user_received_index.sql
-- ============================================================================
-- 优惠券领取记录索引补充（Boot 单体模式）
-- 目标库：aryn_boot
-- 背景：C 端领券列表改为「库存 > 0 或当前用户已领取」的可见性口径后，
--       selectCouponPage 会按 (coupon_id, user_id) 走 correlated EXISTS 子查询；
--       原表仅有主键与 uk_coupon_user_source(tenant_id, user_id, source_type, source_id)，
--       该索引前缀不匹配 coupon_id，会退化成全表扫描。这里补一个覆盖索引。
-- 特性：可重复执行，不执行 DROP/TRUNCATE，不覆盖已有业务数据。
-- 执行：mysql -u root -p aryn_boot < 82coupon_user_received_index.sql

USE `aryn_boot`;

SET NAMES utf8mb4;

SET @coupon_user_index_exists := (
  SELECT COUNT(*)
  FROM information_schema.statistics
  WHERE table_schema = DATABASE()
    AND table_name = 'coupon_user'
    AND index_name = 'idx_coupon_user_coupon_user'
);
SET @coupon_user_index_sql := IF(@coupon_user_index_exists = 0,
  'ALTER TABLE `coupon_user` ADD INDEX `idx_coupon_user_coupon_user` (`coupon_id`, `user_id`)',
  'SELECT 1');
PREPARE coupon_user_index_stmt FROM @coupon_user_index_sql;
EXECUTE coupon_user_index_stmt;
DEALLOCATE PREPARE coupon_user_index_stmt;

-- 自检：added_index 应为 1（按索引名去重计数，该索引含 coupon_id/user_id 两列）。
SELECT
  (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS
     WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'coupon_user'
       AND INDEX_NAME = 'idx_coupon_user_coupon_user') AS added_index;

-- ============================================================================
-- 页面装修模板市场上下架与下载量
-- Source: db/boot/83page_design_template_market_incremental.sql
-- ============================================================================
-- 页面装修模板市场（跨租户模板共享）增量迁移（Boot 单体模式）
-- 目标库：aryn_boot
-- 背景：page_design_template 表新增市场上下架状态与下载量，支持租户将自有模板上架到
--       跨租户模板市场（market_status='1'），其他租户可预览并下载复制为本地模板。
-- 特性：可重复执行（按 information_schema 判断列/索引是否存在），不执行 DROP/TRUNCATE，不覆盖已有业务数据。
-- 执行：mysql -u root -p aryn_boot < 83page_design_template_market_incremental.sql

USE `aryn_boot`;

SET NAMES utf8mb4;

-- 市场状态列（market_status）：0.未上架；1.已上架；2.已下架
SET @market_col_exists = (
  SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'page_design_template' AND COLUMN_NAME = 'market_status'
);
SET @market_ddl = IF(
  @market_col_exists = 0,
  'ALTER TABLE `page_design_template` ADD COLUMN `market_status` char(1) NOT NULL DEFAULT ''0'' COMMENT ''市场状态：0.未上架；1.已上架；2.已下架；'' AFTER `industry_tag`',
  'SELECT 1'
);
PREPARE market_stmt FROM @market_ddl;
EXECUTE market_stmt;
DEALLOCATE PREPARE market_stmt;

-- 下载量列（download_count）：市场模板被其他租户下载复制的累计次数
SET @download_col_exists = (
  SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'page_design_template' AND COLUMN_NAME = 'download_count'
);
SET @download_ddl = IF(
  @download_col_exists = 0,
  'ALTER TABLE `page_design_template` ADD COLUMN `download_count` int NOT NULL DEFAULT 0 COMMENT ''下载量；'' AFTER `market_status`',
  'SELECT 1'
);
PREPARE download_stmt FROM @download_ddl;
EXECUTE download_stmt;
DEALLOCATE PREPARE download_stmt;

-- 市场列表按上架状态/下载量排序的索引（仅在索引不存在时创建）
SET @market_idx_exists = (
  SELECT COUNT(*) FROM information_schema.STATISTICS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'page_design_template' AND INDEX_NAME = 'idx_page_design_template_market'
);
SET @market_idx_ddl = IF(
  @market_idx_exists = 0,
  'ALTER TABLE `page_design_template` ADD KEY `idx_page_design_template_market` (`market_status`,`download_count`)',
  'SELECT 1'
);
PREPARE market_idx_stmt FROM @market_idx_ddl;
EXECUTE market_idx_stmt;
DEALLOCATE PREPARE market_idx_stmt;

-- ============================================================================
-- 模板市场菜单入口与授权
-- Source: db/boot/84template_market_menu.sql
-- ============================================================================
-- 悦航购模板市场菜单入口增量（Boot 单体模式）
-- 目标库：aryn_boot
-- 背景：模板市场浏览页 views/promotion/template-market/index.vue 已就位，但 sys_menu 无入口。
--       在「商城装修」(1527835787455164418) 下新增「模板市场」菜单（sort=20，排于微页面之后），
--       并向已拥有「微页面」(1600477837933047810) 权限的角色/租户推导式补授。
-- 特性：INSERT IGNORE 按固定 ID 幂等；无 DROP/TRUNCATE；重复执行不报错。

USE `aryn_boot`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. 菜单与下载按钮（type='0' 菜单，type='1' 按钮）
INSERT IGNORE INTO `sys_menu` (`id`,`name`,`permission`,`path`,`redirect`,`parent_id`,`icon`,`component`,`sort`,`type`,`create_time`,`outer_status`,`del_flag`,`application_key`,`create_by`) VALUES
('2110000000000000201','模板市场','promotion:pagedesign:template-market','/promotion/template-market',NULL,'1527835787455164418','lucide:store','promotion/template-market/index',20,'0',NOW(),'0','0','app_base','system'),
('2110000000000000202','模板市场下载','promotion:pagedesign:template-market:download',NULL,NULL,'2110000000000000201','',NULL,1,'1',NOW(),'0','0','app_base','system');

-- 2. 试点租户直接授权（PK 与下方推导式同为 MD5(tenant:menu:id)，重复执行/推导命中自动 IGNORE）
INSERT IGNORE INTO `sys_tenant_menu` (`id`,`tenant_id`,`menu_id`,`create_time`,`create_by`)
SELECT MD5(CONCAT('1590229800633634816', ':menu:', m.`id`)), '1590229800633634816', m.`id`, NOW(), 'system'
FROM `sys_menu` m
WHERE m.`id` IN ('2110000000000000201','2110000000000000202')
  AND m.`del_flag` = '0';

-- 3. 角色推导：向已拥有「微页面」菜单的角色补授模板市场菜单与下载按钮
INSERT IGNORE INTO `sys_role_menu` (`id`,`role_id`,`menu_id`,`create_time`,`tenant_id`)
SELECT MD5(CONCAT(gr.`role_id`, ':menu:', m.`id`)), gr.`role_id`, m.`id`, NOW(), gr.`tenant_id`
FROM `sys_menu` m
JOIN `sys_role_menu` gr ON gr.`menu_id` = '1600477837933047810'
WHERE m.`id` IN ('2110000000000000201','2110000000000000202')
  AND m.`del_flag` = '0';

-- 4. 租户推导：向已拥有「微页面」菜单的租户补授模板市场菜单与下载按钮
INSERT IGNORE INTO `sys_tenant_menu` (`id`,`tenant_id`,`menu_id`,`create_time`,`create_by`)
SELECT MD5(CONCAT(gt.`tenant_id`, ':menu:', m.`id`)), gt.`tenant_id`, m.`id`, NOW(), 'system'
FROM `sys_menu` m
JOIN `sys_tenant_menu` gt ON gt.`menu_id` = '1600477837933047810'
WHERE m.`id` IN ('2110000000000000201','2110000000000000202')
  AND m.`del_flag` = '0';

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================================
-- 商超分类扩充与商品图片回填
-- Source: db/boot/86extend_category_seed.sql
-- ============================================================================
-- 悦航购商超分类扩充种子数据（Boot 单体 模式）
--
-- 目标库：aryn_boot（单体模式所有表同库）
-- 背景：参考生鲜电商分类页（新鲜水果/精选冻品/咖啡能量/文具体育等），补齐系统中缺失的
--       1 个一级类目 + 11 个二级类目，并新增 26 个代表商品，
--       全部配图回填 spu_urls / category_pic，登记 sys_material 素材库。
-- 图片实体：db/assets/extend-category-product-images/、db/assets/extend-category-images/（manifest.tsv 清单）
-- 部署方式：将 stored_file 图片放入文件存储根目录 /data/aryn/uploads/{TENANT}/；本脚本只写库。
-- 特性：可重复执行；仅按 98x 前缀与新增类目 id 幂等清理自身数据，不触碰存量业务数据；
--       逻辑删除字段 del_flag，禁止物理删除存量。
--
-- 执行：mysql -u root -p aryn_boot < 86extend_category_seed.sql

USE `aryn_boot`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------- 0. 幂等清理（仅本脚本 98x 前缀与新增类目，不触碰存量） ----------
DELETE FROM `goods_sku` WHERE `id` LIKE '9810000000000000%';
DELETE FROM `goods_spu` WHERE `id` LIKE '9800000000000000%';
DELETE FROM `sys_material` WHERE `id` LIKE '9820000000000000%' OR `id` LIKE '9830000000000000%';
DELETE FROM `goods_category` WHERE `id` IN ('9510000000000000013','9520000000000000055','9520000000000000056','9520000000000000057','9520000000000000058','9520000000000000059','9520000000000000060','9520000000000000061','9520000000000000062','9520000000000000063','9520000000000000064','9520000000000000065');

