        "condition": "always",
        "horizontalScroll": false,
        "marginX": 0,
        "marginY": 6,
        "paddingX": 0,
        "paddingY": 0,
        "radius": 0,
        "sticky": false
      },
      "components": [
        {
          "id": "cat-banner-1",
          "type": "swiper-banner",
          "version": 1,
          "props": {
            "commonStyle": {
              "styleTopMargin": 0,
              "styleBottomMargin": 0,
              "styleLeftMargin": 12,
              "styleRightMargin": 12,
              "styleTopPadding": 0,
              "styleBottomPadding": 0,
              "styleLeftPadding": 0,
              "styleRightPadding": 0,
