-- WHERE sc.`del_flag` = '0'
--   AND (sc.`vessel_call_id` IS NULL OR sc.`vessel_call_id` = ''
--        OR NOT EXISTS (SELECT 1 FROM `vessel_call` lc
--                       WHERE lc.`id` = sc.`vessel_call_id`
--                         AND lc.`del_flag` = '0'
--                         AND lc.`status` IN ('1', '2') AND lc.`etd` > NOW()));

